import{_ as a,o as s,c as o,a0 as n}from"./chunks/framework.DCluYYrN.js";const m=JSON.parse('{"title":"Guias de módulo","description":"","frontmatter":{},"headers":[],"relativePath":"pt_BR/guide/module.md","filePath":"pt_BR/guide/module.md"}'),i={name:"pt_BR/guide/module.md"};function t(d,e,r,l,p,c){return s(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="guias-de-modulo" tabindex="-1">Guias de módulo <a class="header-anchor" href="#guias-de-modulo" aria-label="Permalink to &quot;Guias de módulo&quot;">​</a></h1><p>O KernelSU fornece um mecanismo de módulo que consegue modificar o diretório do sistema enquanto mantém a integridade da partição do sistema. Esse mecanismo é conhecido como &quot;sem sistema&quot;.</p><p>O mecanismo de módulos do KernelSU é quase o mesmo do Magisk. Se você já está familiarizado com o desenvolvimento de módulos Magisk, o desenvolvimento de módulos KernelSU é muito semelhante. Você pode pular a introdução dos módulos abaixo e só precisa ler <a href="./difference-with-magisk.html">Diferenças com Magisk</a>.</p><div class="warning custom-block"><p class="custom-block-title">METAMODULE NECESSÁRIO APENAS PARA MODIFICAÇÃO DE ARQUIVOS DO SISTEMA</p><p>KernelSU usa uma arquitetura <a href="./metamodule.html">metamodule</a> para montar o diretório <code>system</code>. <strong>Somente se seu módulo precisar modificar arquivos <code>/system</code></strong> (via diretório <code>system</code>), você precisa instalar um metamodule (como <a href="https://github.com/tiann/KernelSU/releases" target="_blank" rel="noreferrer">meta-overlayfs</a>). Outros recursos de módulos como scripts, regras sepolicy e system.prop funcionam sem um metamodule.</p></div><h2 id="webui" tabindex="-1">WebUI <a class="header-anchor" href="#webui" aria-label="Permalink to &quot;WebUI&quot;">​</a></h2><p>Os módulos do KernelSU suportam a exibição de interfaces e a interação com os usuários. Para mais detalhes, consulte a <a href="./module-webui.html">documentação do WebUI</a>.</p><h2 id="configuracao-de-modulo" tabindex="-1">Configuração de Módulo <a class="header-anchor" href="#configuracao-de-modulo" aria-label="Permalink to &quot;Configuração de Módulo&quot;">​</a></h2><p>O KernelSU fornece um sistema de configuração integrado que permite que os módulos armazenem configurações de chave-valor persistentes ou temporárias. Para mais detalhes, consulte a <a href="./module-config.html">documentação de Configuração de Módulo</a>.</p><h2 id="scripts-de-execucao-unica" tabindex="-1">Scripts de execução única <a class="header-anchor" href="#scripts-de-execucao-unica" aria-label="Permalink to &quot;Scripts de execução única&quot;">​</a></h2><p>Um ZIP de módulo também pode ser um script de execução única, que o gerenciador do KernelSU executa uma vez em vez de instalar. Para mais detalhes, consulte a <a href="./module-script.html">documentação de Scripts de Execução Única</a>.</p><h2 id="busybox" tabindex="-1">BusyBox <a class="header-anchor" href="#busybox" aria-label="Permalink to &quot;BusyBox&quot;">​</a></h2><p>O KernelSU vem com um recurso binário BusyBox completo (incluindo suporte completo ao SELinux). O executável está localizado em <code>/data/adb/ksu/bin/busybox</code>. O BusyBox do KernelSU suporta &quot;ASH Standalone Shell Mode&quot; alternável em tempo de execução. O que este Modo Autônomo significa é que ao executar no shell <code>ash</code> do BusyBox, cada comando usará diretamente o miniaplicativo dentro do BusyBox, independentemente do que estiver definido em <code>PATH</code>. Por exemplo, comandos como <code>ls</code>, <code>rm</code>, <code>chmod</code> <strong>NÃO</strong> usarão o que está em <code>PATH</code> (no caso do Android, por padrão será <code>/system/bin/ls</code>, <code>/system/bin/rm</code> e <code>/system/bin/chmod</code> respectivamente), mas em vez disso chamará diretamente os miniaplicativos internos do BusyBox. Isso garante que os scripts sempre sejam executados em um ambiente previsível e sempre tenham o conjunto completo de comandos, independentemente da versão do Android em que estão sendo executados. Para forçar um comando a <strong>NÃO</strong> usar o BusyBox, você deve chamar o executável com caminhos completos.</p><p>Cada script shell executado no contexto do KernelSU será executado no shell <code>ash</code> do BusyBox com o Modo Autônomo ativado. Para o que é relevante para desenvolvedores terceirizados, isso inclui todos os scripts de inicialização e scripts de instalação de módulos.</p><p>Para aqueles que desejam usar o recurso Modo Autônomo fora do KernelSU, existem 2 maneiras de ativá-los:</p><ol><li>Definir a variável de ambiente <code>ASH_STANDALONE</code> como <code>1</code>.<br>Exemplo: <code>ASH_STANDALONE=1 /data/adb/ksu/bin/busybox sh &lt;script&gt;</code></li><li>Alternar com opções de linha de comando:<br><code>/data/adb/ksu/bin/busybox sh -o standalone &lt;script&gt;</code></li></ol><p>Para garantir que todos os shells <code>sh</code> subsequentes executados também sejam executados no Modo Autônomo, a opção 1 é o método preferido (e é isso que o KernelSU e o gerenciador do KernelSU usam internamente), pois as variáveis ​​de ambiente são herdadas para os subprocesso.</p><div class="tip custom-block"><p class="custom-block-title">DIFERENÇAS COM MAGISK</p><p>O BusyBox do KernelSU agora está usando o arquivo binário compilado diretamente do projeto Magisk. <strong>Obrigado ao Magisk!</strong> Portanto, você não precisa se preocupar com problemas de compatibilidade entre scripts BusyBox no Magisk e KernelSU porque eles são exatamente iguais!</p></div><h2 id="modulos-kernelsu" tabindex="-1">Módulos KernelSU <a class="header-anchor" href="#modulos-kernelsu" aria-label="Permalink to &quot;Módulos KernelSU&quot;">​</a></h2><p>Um módulo KernelSU é uma pasta colocada em <code>/data/adb/modules</code> com a estrutura abaixo:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/modules</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>├── $MODID                  &lt;--- A pasta é nomeada com o ID do módulo</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Identidade do módulo ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── module.prop         &lt;--- Este arquivo armazena os metadados do módulo</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Conteúdo principal ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── system              &lt;--- Esta pasta será montada se skip_mount não existir</span></span>
<span class="line"><span>│   │   ├── ...</span></span>
<span class="line"><span>│   │   ├── ...</span></span>
<span class="line"><span>│   │   └── ...</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Sinalizadores de status ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── skip_mount          &lt;--- Se existir, o KernelSU não montará sua pasta de sistema</span></span>
<span class="line"><span>│   ├── disable             &lt;--- Se existir, o módulo será desativado</span></span>
<span class="line"><span>│   ├── remove              &lt;--- Se existir, o módulo será removido na próxima reinicialização</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Arquivos opcionais ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── post-fs-data.sh     &lt;--- Este script será executado em post-fs-data</span></span>
<span class="line"><span>│   ├── post-mount.sh       &lt;--- Este script será executado em post-mount</span></span>
<span class="line"><span>│   ├── service.sh          &lt;--- Este script será executado no serviço late_start</span></span>
<span class="line"><span>│   ├── boot-completed.sh   &lt;--- Este script será executado na inicialização concluída</span></span>
<span class="line"><span>|   ├── uninstall.sh        &lt;--- Este script será executado quando o KernelSU remover seu módulo</span></span>
<span class="line"><span>|   ├── action.sh           &lt;--- Este script será executado quando o usuário clicar no botão Ação no KernelSU</span></span>
<span class="line"><span>│   ├── system.prop         &lt;--- As propriedades neste arquivo serão carregadas como propriedades do sistema por resetprop</span></span>
<span class="line"><span>│   ├── sepolicy.rule       &lt;--- Regras adicionais do sepolicy personalizadas</span></span>
<span class="line"><span>│   ├── initrc/             &lt;--- Arquivos .rc neste diretório serão injetados no init.rc no boot</span></span>
<span class="line"><span>│   │   ├── myservice.rc</span></span>
<span class="line"><span>│   │   └── ...</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Gerado automaticamente, NÃO CRIE OU MODIFIQUE MANUALMENTE ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── vendor              &lt;--- Um link simbólico para $MODID/system/vendor</span></span>
<span class="line"><span>│   ├── product             &lt;--- Um link simbólico para $MODID/system/product</span></span>
<span class="line"><span>│   ├── system_ext          &lt;--- Um link simbólico para $MODID/system/system_ext</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   │      *** Quaisquer arquivos/pastas adicionais são permitidos ***</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── ...</span></span>
<span class="line"><span>│   └── ...</span></span>
<span class="line"><span>|</span></span>
<span class="line"><span>├── another_module</span></span>
<span class="line"><span>│   ├── .</span></span>
<span class="line"><span>│   └── .</span></span>
<span class="line"><span>├── .</span></span>
<span class="line"><span>├── .</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">DIFERENÇAS COM MAGISK</p><p>O KernelSU não possui suporte integrado para o Zygisk, portanto não há conteúdo relacionado ao Zygisk no módulo. No entanto, você pode usar <a href="https://github.com/Dr-TSNG/ZygiskNext" target="_blank" rel="noreferrer">ZygiskNext</a> para suportar módulos Zygisk. Neste caso, o conteúdo do módulo Zygisk é idêntico ao suportado pelo Magisk.</p></div><h3 id="module-prop" tabindex="-1">module.prop <a class="header-anchor" href="#module-prop" aria-label="Permalink to &quot;module.prop&quot;">​</a></h3><p><code>module.prop</code> é um arquivo de configuração para um módulo. No KernelSU, se um módulo não contiver este arquivo, ele não será reconhecido como um módulo. O formato deste arquivo é o seguinte:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>id=&lt;string&gt;</span></span>
<span class="line"><span>name=&lt;string&gt;</span></span>
<span class="line"><span>version=&lt;string&gt;</span></span>
<span class="line"><span>versionCode=&lt;int&gt;</span></span>
<span class="line"><span>author=&lt;string&gt;</span></span>
<span class="line"><span>description=&lt;string&gt;</span></span>
<span class="line"><span>updateJson=&lt;url&gt; (opcional)</span></span>
<span class="line"><span>actionIcon=&lt;path&gt; (opcional)</span></span>
<span class="line"><span>webuiIcon=&lt;path&gt; (opcional)</span></span></code></pre></div><ul><li><code>id</code> deve corresponder a esta expressão regular: <code>^[a-zA-Z][a-zA-Z0-9._-]+$</code><br> Exemplo: ✓ <code>a_module</code>, ✓ <code>a.module</code>, ✓ <code>module-101</code>, ✗ <code>a module</code>, ✗ <code>1_module</code>, ✗ <code>-a-module</code><br> Este é o <strong>identificador exclusivo</strong> do seu módulo. Você não deve alterá-lo depois de publicado.</li><li><code>versionCode</code> deve ser um <strong>número inteiro</strong>. Isso é usado para comparar versões.</li><li>Outros que não foram mencionados acima podem ser qualquer string de <strong>linha única</strong>.</li><li>Certifique-se de usar o tipo de quebra de linha <code>UNIX (LF)</code> e não o <code>Windows (CR+LF)</code> ou <code>Macintosh (CR)</code>.</li><li><code>actionIcon</code> e <code>webuiIcon</code> são caminhos de imagem opcionais usados como ícones padrão para o atalho de ação do módulo e o atalho WebUI do módulo no aplicativo gerenciador. Esses caminhos devem ser relativos ao diretório raiz do módulo. Por exemplo, <code>actionIcon=icon/icon.png</code> será resolvido como <code>&lt;MODDIR&gt;/icon/icon.png</code>.</li></ul><div class="tip custom-block"><p class="custom-block-title">DESCRIÇÃO DINÂMICA</p><p>O campo <code>description</code> pode ser substituído dinamicamente em tempo de execução usando o sistema de configuração de módulos. Veja <a href="./module-config.html#overriding-module-description">Substituindo a Descrição do Módulo</a> para detalhes.</p></div><h3 id="shell-scripts" tabindex="-1">Shell scripts <a class="header-anchor" href="#shell-scripts" aria-label="Permalink to &quot;Shell scripts&quot;">​</a></h3><p>Por favor, leia a seção <a href="#scripts-de-inicializacao">Scripts de inicialização</a> para entender a diferença entre <code>post-fs-data.sh</code> e <code>service.sh</code>. Para a maioria dos desenvolvedores de módulos, <code>service.sh</code> deve ser bom o suficiente se você precisar apenas executar um script de inicialização. Se precisar executar o script após a inicialização ser concluída, use <code>boot-completed.sh</code>. Se você quiser fazer algo após montar OverlayFS, use <code>post-mount.sh</code>.</p><p>Em todos os scripts do seu módulo, use <code>MODDIR=\${0%/*}</code> para obter o caminho do diretório base do seu módulo, <strong>NÃO</strong> codifique o caminho do seu módulo nos scripts.</p><div class="tip custom-block"><p class="custom-block-title">DIFERENÇAS COM MAGISK</p><p>Você pode usar a variável de ambiente <code>KSU</code> para determinar se um script está sendo executado no KernelSU ou Magisk. Se estiver executando no KernelSU, esse valor será definido como <code>true</code>.</p></div><h3 id="diretorio-system" tabindex="-1">Diretório <code>system</code> <a class="header-anchor" href="#diretorio-system" aria-label="Permalink to &quot;Diretório \`system\`&quot;">​</a></h3><p>O conteúdo deste diretório será sobreposto à partição <code>/system</code> do sistema usando OverlayFS após a inicialização do sistema. Isso significa que:</p><ol><li>Arquivos com o mesmo nome daqueles no diretório correspondente no sistema serão substituídos pelos arquivos deste diretório.</li><li>Pastas com o mesmo nome daquelas no diretório correspondente no sistema serão mescladas com as pastas neste diretório.</li></ol><p>Se você deseja excluir um arquivo ou pasta no diretório original do sistema, você precisa criar um arquivo com o mesmo nome do arquivo/pasta no diretório do módulo usando <code>mknod filename c 0 0</code>. Dessa forma, o sistema OverlayFS irá automaticamente &quot;branquear&quot; este arquivo como se ele tivesse sido excluído (a partição /system não foi realmente alterada).</p><p>Você também pode declarar uma variável chamada <code>REMOVE</code> contendo uma lista de diretórios em <code>customize.sh</code> para executar operações de remoção, e o KernelSU executará automaticamente <code>mknod &lt;TARGET&gt; c 0 0</code> nos diretórios correspondentes do módulo. Por exemplo:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REMOVE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/YouTube</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/Bloatware</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>A lista acima irá executar <code>mknod $MODPATH/system/app/YouTube c 0 0</code> e <code>mknod $MODPATH/system/app/Bloatware c 0 0</code>, <code>/system/app/YouTube</code> e <code>/system/app/Bloatware</code> serão removidos após o módulo entrar em vigor.</p><p>Se você deseja substituir um diretório no sistema, você precisa criar um diretório com o mesmo caminho no diretório do módulo e, em seguida, definir o atributo <code>setfattr -n trusted.overlay.opaque -v y &lt;TARGET&gt;</code> para este diretório. Desta forma, o sistema OverlayFS substituirá automaticamente o diretório correspondente no sistema (sem alterar a partição /system).</p><p>Você pode declarar uma variável chamada <code>REPLACE</code> em seu arquivo <code>customize.sh</code>, que inclui uma lista de diretórios a serem substituídos, e o KernelSU executará automaticamente as operações correspondentes em seu diretório de módulo. Por exemplo:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REPLACE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/YouTube</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/system/app/Bloatware</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>Esta lista criará automaticamente os diretórios <code>$MODPATH/system/app/YouTube</code> e <code>$MODPATH/system/app/Bloatware</code> e, em seguida, executará <code>setfattr -n trusted.overlay.opaque -v y $MODPATH/system/app/YouTube</code> e <code>setfattr -n trusted.overlay.opaque -v y $MODPATH/system/app/Bloatware</code>. Após o módulo entrar em vigor, <code>/system/app/YouTube</code> e <code>/system/app/Bloatware</code> serão substituídos por diretórios vazios.</p><div class="tip custom-block"><p class="custom-block-title">DIFERENÇAS COM MAGISK</p><p>O mecanismo sem sistema do KernelSU é implementado através do OverlayFS do kernel, enquanto o Magisk atualmente usa montagem mágica (montagem de ligação). Os dois métodos de implementação têm diferenças significativas, mas o objetivo final é o mesmo: modificar os arquivos <code>/system</code> sem modificar fisicamente a partição <code>/system</code>.</p></div><p>Se você estiver interessado em OverlayFS, é recomendável ler a <a href="https://docs.kernel.org/filesystems/overlayfs.html" target="_blank" rel="noreferrer">documentação sobre OverlayFS</a> do kernel Linux.</p><h3 id="system-prop" tabindex="-1">system.prop <a class="header-anchor" href="#system-prop" aria-label="Permalink to &quot;system.prop&quot;">​</a></h3><p>Este arquivo segue o mesmo formato de <code>build.prop</code>. Cada linha é composta por <code>[key]=[value]</code>.</p><h3 id="sepolicy-rule" tabindex="-1">sepolicy.rule <a class="header-anchor" href="#sepolicy-rule" aria-label="Permalink to &quot;sepolicy.rule&quot;">​</a></h3><p>Se o seu módulo exigir alguns patches adicionais do sepolicy, adicione essas regras a este arquivo. Cada linha neste arquivo será tratada como uma declaração de política.</p><h3 id="initrc-injection" tabindex="-1">Injeção de initrc <a class="header-anchor" href="#initrc-injection" aria-label="Permalink to &quot;Injeção de initrc {#initrc-injection}&quot;">​</a></h3><p>O KernelSU fornece um mecanismo para injetar diretivas RC customizadas do Android Init no <code>init.rc</code> do sistema. Isso permite que os módulos registrem serviços Android customizados, definam gatilhos de propriedade ou executem outras ações de linguagem Init sem modificar a partição do sistema.</p><p>Durante a inicialização, o módulo do kernel KernelSU intercepta as chamadas de sistema <code>read()</code> e <code>fstat()</code>. Quando o processo init do Android lê <code>/system/etc/init/hw/init.rc</code>, o KernelSU adiciona de forma transparente o conteúdo RC customizado ao final do arquivo. O processo init analisa essas diretivas injetadas exatamente como o conteúdo original do init.rc.</p><p>No lado do espaço do usuário, o ksud concatena todos os arquivos <code>.rc</code> de módulos habilitados em um único arquivo <code>modules.rc</code>, armazenado na partição <code>/metadata</code>. Este arquivo é regenerado automaticamente sempre que o estado de um módulo muda (instalar, habilitar, desabilitar, desinstalar, etc.).</p><h4 id="arquivos-initrc-do-modulo" tabindex="-1">Arquivos initrc do módulo <a class="header-anchor" href="#arquivos-initrc-do-modulo" aria-label="Permalink to &quot;Arquivos initrc do módulo&quot;">​</a></h4><p>Crie um subdiretório <code>initrc/</code> no diretório do seu módulo e coloque seus arquivos <code>.rc</code> lá:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/modules/&lt;MODID&gt;/</span></span>
<span class="line"><span>├── initrc/</span></span>
<span class="line"><span>│   ├── myservice.rc</span></span>
<span class="line"><span>│   └── another.rc</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>Os arquivos devem ter uma extensão <code>.rc</code>.</li><li>Contanto que o módulo esteja habilitado, todos os arquivos <code>.rc</code> no diretório <code>initrc/</code> serão incluídos (permissão de execução não é necessária).</li><li>Os arquivos são processados em <strong>ordem alfabética de nome de arquivo</strong> dentro do diretório, e os módulos são processados em <strong>ordem alfabética de ID do módulo</strong>.</li></ul></div><h4 id="arquivos-initrc-gerais" tabindex="-1">Arquivos initrc gerais <a class="header-anchor" href="#arquivos-initrc-gerais" aria-label="Permalink to &quot;Arquivos initrc gerais&quot;">​</a></h4><p>Além de arquivos RC no nível do módulo, você pode colocar arquivos <code>.rc</code> no diretório global:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/adb/initrc.d/</span></span>
<span class="line"><span>├── myservice.rc</span></span>
<span class="line"><span>└── another.rc</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Arquivos initrc gerais requerem permissão de execução</p><p>Diferente do diretório <code>initrc/</code> do módulo, arquivos em <code>/data/adb/initrc.d/</code> <strong>devem ter permissões de execução</strong> para serem incluídos. Arquivos <code>.rc</code> não executáveis serão ignorados silenciosamente.</p></div><p>Arquivos <code>initrc.d/</code> gerais são processados antes de quaisquer arquivos RC de módulo.</p><h4 id="exemplo" tabindex="-1">Exemplo <a class="header-anchor" href="#exemplo" aria-label="Permalink to &quot;Exemplo&quot;">​</a></h4><p>Aqui está um exemplo de arquivo <code>.rc</code> que registra um serviço Android customizado:</p><div class="language-rc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>service myservice /data/adb/modules/mymodule/bin/myservice</span></span>
<span class="line"><span>    user root</span></span>
<span class="line"><span>    group root</span></span>
<span class="line"><span>    disabled</span></span>
<span class="line"><span>    seclabel u:r:ksu:s0</span></span>
<span class="line"><span></span></span>
<span class="line"><span>on property:sys.boot_completed=1</span></span>
<span class="line"><span>    start myservice</span></span></code></pre></div><p>Se este arquivo for colocado em <code>/data/adb/modules/mymodule/initrc/myservice.rc</code>, ele registrará um serviço chamado <code>myservice</code> na inicialização e o iniciará quando <code>sys.boot_completed=1</code> for alcançado.</p><h4 id="atualizacao-manual" tabindex="-1">Atualização Manual <a class="header-anchor" href="#atualizacao-manual" aria-label="Permalink to &quot;Atualização Manual&quot;">​</a></h4><p>Você pode acionar manualmente a regeneração do <code>modules.rc</code> com o seguinte comando (as alterações entram em vigor na próxima inicialização):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ksud</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> initrc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> refresh</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>A injeção de initrc acontece extremamente cedo no processo de inicialização (quando o init lê o init.rc), <strong>antes</strong> do post-fs-data e de quaisquer scripts de módulo serem executados.</li><li>O conteúdo RC injetado é tratado pelo init como parte do init.rc original, suportando toda a sintaxe da linguagem Android Init (definições de serviço, gatilhos, configurações de propriedades, etc.).</li><li>A injeção de initrc <strong>não está disponível</strong> no <strong>modo late-load</strong>, pois os ganchos de chamada do sistema não são instalados nesse modo.</li><li>A injeção de RC do módulo pode ser desabilitada passando o parâmetro <code>--no-custom-rc</code> ao aplicar patch na imagem com o ksud.</li></ul></div><h2 id="instalador-do-modulo" tabindex="-1">Instalador do módulo <a class="header-anchor" href="#instalador-do-modulo" aria-label="Permalink to &quot;Instalador do módulo&quot;">​</a></h2><p>Um instalador do módulo KernelSU é um módulo KernelSU empacotado em um arquivo ZIP que pode ser atualizado no gerenciador do KernelSU. O instalador do módulo KernelSU mais simples é apenas um módulo KernelSU compactado como um arquivo ZIP.</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>module.zip</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├── customize.sh                       &lt;--- (Opcional, mais detalhes posteriormente)</span></span>
<span class="line"><span>│                                           Este script será fornecido por update-binary</span></span>
<span class="line"><span>├── ...</span></span>
<span class="line"><span>├── ...  /* O resto dos arquivos do módulo */</span></span>
<span class="line"><span>│</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">AVISO</p><p>O módulo KernelSU <strong>NÃO</strong> é compatível para instalação no Recovery personalizado!</p></div><h3 id="personalizacao" tabindex="-1">Personalização <a class="header-anchor" href="#personalizacao" aria-label="Permalink to &quot;Personalização&quot;">​</a></h3><p>Se você precisar personalizar o processo de instalação do módulo, opcionalmente você pode criar um script no instalador chamado <code>customize.sh</code>. Este script será <strong>sourced</strong> (não executado) pelo script do instalador do módulo depois que todos os arquivos forem extraídos e as permissões padrão e o contexto secundário forem aplicados. Isso é muito útil se o seu módulo exigir configuração adicional com base na ABI do dispositivo ou se você precisar definir permissões/secontext especiais para alguns dos arquivos do seu módulo.</p><p>Se você quiser controlar e personalizar totalmente o processo de instalação, declare <code>SKIPUNZIP=1</code> em <code>customize.sh</code> para pular todas as etapas de instalação padrão. Ao fazer isso, seu <code>customize.sh</code> será responsável por instalar tudo sozinho.</p><p>O script <code>customize.sh</code> é executado no shell BusyBox <code>ash</code> do KernelSU com o Modo Autônomo ativado. As seguintes variáveis ​​e funções estão disponíveis:</p><h4 id="variaveis" tabindex="-1">Variáveis <a class="header-anchor" href="#variaveis" aria-label="Permalink to &quot;Variáveis&quot;">​</a></h4><ul><li><code>KSU</code> (bool): uma variável para marcar que o script está sendo executado no ambiente KernelSU, e o valor desta variável sempre será <code>true</code>. Você pode usá-lo para distinguir entre KernelSU e Magisk.</li><li><code>KSU_VER</code> (string): a string da versão do KernelSU atualmente instalado (ex.: <code>v0.4.0</code>).</li><li><code>KSU_VER_CODE</code> (int): o código da versão do KernelSU atualmente instalado no espaço do usuário (ex.: <code>10672</code>).</li><li><code>KSU_KERNEL_VER_CODE</code> (int): o código da versão do KernelSU atualmente instalado no espaço do kernel (ex.: <code>10672</code>).</li><li><code>BOOTMODE</code> (bool): sempre será <code>true</code> no KernelSU.</li><li><code>MODPATH</code> (path): o caminho onde os arquivos do seu módulo devem ser instalados.</li><li><code>TMPDIR</code> (path): um lugar onde você pode armazenar arquivos temporariamente.</li><li><code>ZIPFILE</code> (path): ZIP de instalação do seu módulo.</li><li><code>ARCH</code> (string): a arquitetura da CPU do dispositivo. O valor é <code>arm</code>, <code>arm64</code>, <code>x86</code> ou <code>x64</code>.</li><li><code>IS64BIT</code> (bool): <code>true</code> se <code>$ARCH</code> for <code>arm64</code> ou <code>x64</code>.</li><li><code>API</code> (int): o nível da API (versão do Android) do dispositivo (ex.: <code>23</code> para Android 6.0).</li><li><code>KSU_UAPI_VER</code> (int): a versão UAPI do espaço do usuário do KernelSU (ksud) (ex.: <code>2</code>). Esta versão é incrementada quando há alterações que quebram a compatibilidade no driver do kernel, e pode ser usada pelos módulos para verificar compatibilidade.</li><li><code>KSU_RUNTIME_MODE</code> (string): o modo de execução atual do KernelSU. Os valores possíveis são <code>built-in</code> (modo GKI, compilado no kernel), <code>lkm</code> (carregado como módulo do kernel na inicialização) ou <code>late-load</code> (carregado como módulo do kernel após a inicialização).</li><li><code>KSU_LATE_LOAD</code> (int?): se o KernelSU foi carregado tardiamente após a inicialização, esta variável é definida como <code>1</code>; caso contrário, não é definida.</li></ul><div class="warning custom-block"><p class="custom-block-title">AVISO</p><p>No KernelSU, <code>MAGISK_VER_CODE</code> é sempre <code>25200</code> e <code>MAGISK_VER</code> é sempre <code>v25.2</code>. Por favor, não use essas duas variáveis ​​para determinar se ele está sendo executado no KernelSU ou não.</p></div><h4 id="funcoes" tabindex="-1">Funções <a class="header-anchor" href="#funcoes" aria-label="Permalink to &quot;Funções&quot;">​</a></h4><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ui_print &lt;msg&gt;</span></span>
<span class="line"><span>    imprima &lt;msg&gt; no console</span></span>
<span class="line"><span>    Evite usar &#39;echo&#39;, pois ele não será exibido no console de recovery personalizado</span></span>
<span class="line"><span></span></span>
<span class="line"><span>abort &lt;msg&gt;</span></span>
<span class="line"><span>    imprima mensagem de erro &lt;msg&gt; para consolar e encerrar a instalação</span></span>
<span class="line"><span>    Evite usar &#39;exit&#39;, pois isso irá pular as etapas de limpeza de encerramento</span></span>
<span class="line"><span></span></span>
<span class="line"><span>set_perm &lt;target&gt; &lt;owner&gt; &lt;group&gt; &lt;permission&gt; [context]</span></span>
<span class="line"><span>    se [context] não estiver definido, o padrão é &quot;u:object_r:system_file:s0&quot;</span></span>
<span class="line"><span>    esta função é uma abreviação para os seguintes comandos:</span></span>
<span class="line"><span>       chown owner.group target</span></span>
<span class="line"><span>       chmod permission target</span></span>
<span class="line"><span>       chcon context target</span></span>
<span class="line"><span></span></span>
<span class="line"><span>set_perm_recursive &lt;directory&gt; &lt;owner&gt; &lt;group&gt; &lt;dirpermission&gt; &lt;filepermission&gt; [context]</span></span>
<span class="line"><span>    se [context] não está definido, o padrão é &quot;u:object_r:system_file:s0&quot;</span></span>
<span class="line"><span>    para todos os arquivos em &lt;directory&gt;, ele chamará:</span></span>
<span class="line"><span>       set_perm arquivo proprietário do grupo filepermission</span></span>
<span class="line"><span>    para todos os diretórios em &lt;directory&gt; (incluindo ele mesmo), ele vai ligar:</span></span>
<span class="line"><span>       set_perm dir owner group dirpermission context</span></span></code></pre></div><h2 id="scripts-de-inicializacao" tabindex="-1">Scripts de inicialização <a class="header-anchor" href="#scripts-de-inicializacao" aria-label="Permalink to &quot;Scripts de inicialização&quot;">​</a></h2><p>No KernelSU, os scripts são divididos em dois tipos com base em seu modo de execução: modo post-fs-data e modo de serviço late_start.</p><ul><li>modo post-fs-data <ul><li>Esta etapa está BLOQUEANDO. O processo de inicialização é pausado antes da conclusão da execução ou após 10 segundos.</li><li>Os scripts são executados antes de qualquer módulo ser montado. Isso permite que um desenvolvedor de módulo ajuste dinamicamente seus módulos antes de serem montados.</li><li>Este estágio acontece antes do início do Zygote, o que significa praticamente tudo no Android.</li><li><strong>AVISO:</strong> Usar <code>setprop</code> irá bloquear o processo de inicialização! Por favor, use <code>resetprop -n &lt;prop_name&gt; &lt;prop_value&gt;</code> em vez disso.</li><li><strong>Execute scripts neste modo apenas se necessário</strong>.</li></ul></li><li>modo de serviço late_start <ul><li>Esta etapa é SEM BLOQUEIO. Seu script é executado em paralelo com o restante do processo de inicialização.</li><li><strong>Este é o estágio recomendado para executar a maioria dos scripts</strong>.</li></ul></li></ul><p>No KernelSU, os scripts de inicialização são divididos em dois tipos com base no local de armazenamento: scripts gerais e scripts de módulo.</p><ul><li>Scripts gerais <ul><li>Colocado em <code>/data/adb/post-fs-data.d</code>, <code>/data/adb/service.d</code>, <code>/data/adb/post-mount.d</code> ou <code>/data/adb/boot-completed.d</code>.</li><li>Somente executado se o script estiver definido como executável (<code>chmod +x script.sh</code>).</li><li>Os scripts em <code>post-fs-data.d</code> são executados no modo post-fs-data e os scripts em <code>service.d</code> são executados no modo de serviço late_start.</li><li>Os módulos <strong>NÃO</strong> devem adicionar scripts gerais durante a instalação.</li></ul></li><li>Scripts de módulo <ul><li>Colocado na própria pasta do módulo.</li><li>Executado apenas se o módulo estiver ativado.</li><li><code>post-fs-data.sh</code> é executado no modo post-fs-data, <code>service.sh</code> é executado no modo de serviço late_start, <code>boot-completed.sh</code> é executado na inicialização concluída e <code>post-mount.sh</code> é executado no OverlayFS montado.</li></ul></li></ul><p>Todos os scripts de inicialização serão executados no shell BusyBox <code>ash</code> do KernelSU com o Modo Autônomo ativado.</p><h3 id="explicacao-do-processo-de-scripts-de-inicializacao" tabindex="-1">Explicação do processo de scripts de inicialização <a class="header-anchor" href="#explicacao-do-processo-de-scripts-de-inicializacao" aria-label="Permalink to &quot;Explicação do processo de scripts de inicialização&quot;">​</a></h3><p>A seguir está o processo de inicialização relevante para o Android (algumas partes foram omitidas), que inclui a operação do KernelSU (com asteriscos iniciais) e pode ajudá-lo a entender melhor o propósito desses scripts de módulo:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0. Bootloader (nada nesta tela)</span></span>
<span class="line"><span>load patched boot.img</span></span>
<span class="line"><span>load kernel:</span></span>
<span class="line"><span>    - Modo GKI: kernel GKI com KernelSU integrado</span></span>
<span class="line"><span>    - Modo LKM: kernel stock</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. kernel exec init (logo OEM na tela):</span></span>
<span class="line"><span>    - Modo GKI: stock init</span></span>
<span class="line"><span>    - Modo LKM: exec ksuinit, insmod kernelsu.ko, exec stock init</span></span>
<span class="line"><span>mount /dev, /dev/pts, /proc, /sys, etc.</span></span>
<span class="line"><span>property-init -&gt; read default props</span></span>
<span class="line"><span>read init.rc</span></span>
<span class="line"><span>  *initrc injection: Kernel hook appends KernelSU core RC and module modules.rc to init.rc</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>early-init -&gt; init -&gt; late_init</span></span>
<span class="line"><span>early-fs</span></span>
<span class="line"><span>   start vold</span></span>
<span class="line"><span>fs</span></span>
<span class="line"><span>  mount /vendor, /system, /persist, etc.</span></span>
<span class="line"><span>post-fs-data</span></span>
<span class="line"><span>  *verificação do modo de segurança</span></span>
<span class="line"><span>  *executar scripts gerais em post-fs-data.d/</span></span>
<span class="line"><span>  *carregar sepolicy.rule</span></span>
<span class="line"><span>  *montar tmpfs</span></span>
<span class="line"><span>  *executar scripts de módulo post-fs-data.sh</span></span>
<span class="line"><span>    **(Zygisk)./bin/zygisk-ptrace64 monitor</span></span>
<span class="line"><span>  *(pré)carregamento de system.prop (igual a resetprop -n)</span></span>
<span class="line"><span>  *remontar módulos em /system</span></span>
<span class="line"><span>  *executar scripts gerais em post-mount.d/</span></span>
<span class="line"><span>  *executar scripts de módulo post-mount.sh</span></span>
<span class="line"><span>zygote-start</span></span>
<span class="line"><span>load_all_props_action</span></span>
<span class="line"><span>  *executar resetprop (defina adereços reais para resetprop com a opção -n)</span></span>
<span class="line"><span>... -&gt; boot</span></span>
<span class="line"><span>  class_start core</span></span>
<span class="line"><span>    start-service logd, console, vold, etc.</span></span>
<span class="line"><span>  class_start main</span></span>
<span class="line"><span>    start-service adb, netd (iptables), zygote, etc.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2. kernel2user init (animação da ROM na tela, inicie pelo serviço bootanim)</span></span>
<span class="line"><span>*executar scripts gerais em service.d/</span></span>
<span class="line"><span>*executar scripts de módulo service.sh</span></span>
<span class="line"><span>*definir adereços para resetprop sem a opção -p</span></span>
<span class="line"><span>  **(Zygisk) hook zygote (iniciar o zygiskd)</span></span>
<span class="line"><span>  **(Zygisk) montar zygisksu/module.prop</span></span>
<span class="line"><span>iniciar apps do sistema (início automático)</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>inicialização completa (transmitir evento ACTION_BOOT_COMPLETED)</span></span>
<span class="line"><span>*executar scripts gerais em boot-completed.d/</span></span>
<span class="line"><span>*executar scripts de módulo boot-completed.sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>3. Operável pelo usuário (tela de bloqueio)</span></span>
<span class="line"><span>insira a senha para descriptografar /data/data</span></span>
<span class="line"><span>*conjunto real de adereços para resetprop com opção -p</span></span>
<span class="line"><span>iniciar apps de usuário (início automático)</span></span></code></pre></div><p>Se você estiver interessado na linguagem de inicialização do Android, é recomendável ler sua <a href="https://android.googlesource.com/platform/system/core/+/master/init/README.md" target="_blank" rel="noreferrer">documentação</a>.</p><h2 id="late-load-mode" tabindex="-1">Modo late-load <a class="header-anchor" href="#late-load-mode" aria-label="Permalink to &quot;Modo late-load {#late-load-mode}&quot;">​</a></h2><p>Além do fluxo de inicialização padrão descrito acima, o KernelSU suporta um <strong>modo late-load</strong> para cenários de LKM (Loadable Kernel Module). Neste modo, o módulo do kernel KernelSU é carregado <strong>após o sistema ter sido totalmente iniciado</strong>, em vez de durante o processo init.</p><h3 id="quando-o-late-load-acontece" tabindex="-1">Quando o late-load acontece? <a class="header-anchor" href="#quando-o-late-load-acontece" aria-label="Permalink to &quot;Quando o late-load acontece?&quot;">​</a></h3><p>O late-load é acionado executando o comando <code>ksud late-load</code>. Este comando:</p><ol><li>Detecta a versão KMI atual e carrega o <code>kernelsu.ko</code> correspondente dos recursos incorporados.</li><li>Realiza a inicialização do módulo (regras SELinux, lista de permissões, features, etc.) que normalmente aconteceria durante a inicialização.</li></ol><p>Como o sistema já está totalmente em execução, certos mecanismos de tempo de inicialização estão indisponíveis ou são desnecessários.</p><h3 id="diferencas-em-relacao-a-inicializacao-padrao" tabindex="-1">Diferenças em relação à inicialização padrão <a class="header-anchor" href="#diferencas-em-relacao-a-inicializacao-padrao" aria-label="Permalink to &quot;Diferenças em relação à inicialização padrão&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Comportamento</th><th style="text-align:center;">Inicialização padrão</th><th style="text-align:center;">Modo late-load</th></tr></thead><tbody><tr><td>Módulo do kernel carregado pelo init (PID 1)</td><td style="text-align:center;">Sim</td><td style="text-align:center;">Não (carregado após inicialização)</td></tr><tr><td>Hooks kprobe do ksud (execve/read/fstat/input)</td><td style="text-align:center;">Sim</td><td style="text-align:center;">Ignorado</td></tr><tr><td>Detecção de modo seguro (tecla de volume)</td><td style="text-align:center;">Sim</td><td style="text-align:center;">Sempre desativado</td></tr><tr><td>Captura de log de inicialização (logcat/dmesg)</td><td style="text-align:center;">Sim</td><td style="text-align:center;">Ignorado</td></tr><tr><td>Verificação de coexistência com Magisk</td><td style="text-align:center;">Sim</td><td style="text-align:center;">Ignorado</td></tr><tr><td>Evento <code>post-fs-data</code> reportado ao kernel</td><td style="text-align:center;">Sim</td><td style="text-align:center;">Ignorado</td></tr><tr><td>Evento <code>boot-completed</code> reportado ao kernel</td><td style="text-align:center;">Sim</td><td style="text-align:center;">Definido diretamente durante init</td></tr><tr><td>Scripts <code>post-fs-data.sh</code> / <code>post-fs-data.d/</code></td><td style="text-align:center;">Sim</td><td style="text-align:center;">Substituído pelo estágio <code>late-load</code></td></tr><tr><td>Carregamento de <code>system.prop</code></td><td style="text-align:center;">Sim</td><td style="text-align:center;">Sim</td></tr><tr><td>Montagem OverlayFS (metamodule)</td><td style="text-align:center;">Sim</td><td style="text-align:center;">Sim</td></tr><tr><td>Scripts <code>post-mount.sh</code> / <code>post-mount.d/</code></td><td style="text-align:center;">Sim</td><td style="text-align:center;">Sim</td></tr><tr><td>Scripts <code>service.sh</code> / <code>service.d/</code></td><td style="text-align:center;">Sim</td><td style="text-align:center;">Sim</td></tr><tr><td>Scripts <code>boot-completed.sh</code> / <code>boot-completed.d/</code></td><td style="text-align:center;">Sim</td><td style="text-align:center;">Sim</td></tr><tr><td>Variável de ambiente <code>KSU_LATE_LOAD</code></td><td style="text-align:center;">Não definida</td><td style="text-align:center;">Definida como <code>1</code></td></tr><tr><td>Flag de info do kernel <code>0x4</code></td><td style="text-align:center;">Não definida</td><td style="text-align:center;">Definida</td></tr></tbody></table><h3 id="ordem-de-execucao-dos-scripts" tabindex="-1">Ordem de execução dos scripts <a class="header-anchor" href="#ordem-de-execucao-dos-scripts" aria-label="Permalink to &quot;Ordem de execução dos scripts&quot;">​</a></h3><p>No modo late-load, a ordem de execução dos scripts é:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ksud late-load:</span></span>
<span class="line"><span>  1. Carregar kernelsu.ko (se ainda não carregado)</span></span>
<span class="line"><span>  2. Extrair binários, processar atualizações de módulos, carregar regras SELinux, inicializar features</span></span>
<span class="line"><span>  3. Executar scripts late-load.d/ e scripts late-load dos módulos (bloqueante)</span></span>
<span class="line"><span>  4. Carregar system.prop (resetprop -n)</span></span>
<span class="line"><span>  5. Executar script de montagem do metamodule (OverlayFS)</span></span>
<span class="line"><span>  6. Executar scripts post-mount.d/ e post-mount.sh dos módulos (bloqueante)</span></span>
<span class="line"><span>  7. Executar scripts service.d/ e service.sh dos módulos (não bloqueante)</span></span>
<span class="line"><span>  8. Executar scripts boot-completed.d/ e boot-completed.sh dos módulos (não bloqueante)</span></span></code></pre></div><h3 id="scripts-especificos-do-late-load" tabindex="-1">Scripts específicos do late-load <a class="header-anchor" href="#scripts-especificos-do-late-load" aria-label="Permalink to &quot;Scripts específicos do late-load&quot;">​</a></h3><p>Módulos podem fornecer um script <code>late-load.sh</code> que é executado <strong>apenas</strong> no modo late-load, como substituto do <code>post-fs-data.sh</code>. Este script é executado antes da montagem do OverlayFS, similar ao <code>post-fs-data.sh</code> no fluxo padrão.</p><p>Além disso, scripts gerais podem ser colocados em <code>/data/adb/late-load.d/</code> para serem executados neste estágio.</p><h3 id="detectando-o-modo-late-load-nos-scripts" tabindex="-1">Detectando o modo late-load nos scripts <a class="header-anchor" href="#detectando-o-modo-late-load-nos-scripts" aria-label="Permalink to &quot;Detectando o modo late-load nos scripts&quot;">​</a></h3><p>Módulos podem detectar o modo late-load verificando a variável de ambiente <code>KSU_LATE_LOAD</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$KSU_LATE_LOAD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;1&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ]; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Executando no modo late-load</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Late-load mode detected&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fi</span></span></code></pre></div><p>Isso permite que os módulos ajustem seu comportamento de acordo, por exemplo, pulando operações que só são necessárias durante a inicialização antecipada.</p>`,109)])])}const h=a(i,[["render",t]]);export{m as __pageData,h as default};
